const leadData = $json;

const cleanedData = {
  leadId: leadData.Lead_ID || `LEAD_${Date.now()}`,
  name: leadData.Name || $input.first().json['Name '],
  email: leadData.Email || $input.first().json['  Email  '],
  company: leadData.Company || $input.first().json['  Company  '],
  budget: leadData.Budget || $input.first().json['  Budget  '],
  timeline: leadData.Timeline || $input.first().json.Timeline,
  source: leadData.Source || $input.first().json['  Source  '],
  notes: leadData.Notes || $input.first().json['  Notes  '],
  rowNumber: leadData.__rowNumber
};

return [{ json: cleanedData }];

// COMPLETE ERROR-PROOF CODE FOR n8n CODE NODE
// This handles all possible node reference issues

function calculateLeadScore(aiResponse, leadData) {
  try {
    // Parse AI response
    let scores;
    if (typeof aiResponse === 'string') {
      // Extract JSON from AI response if it's wrapped in text
      const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
      scores = jsonMatch ? JSON.parse(jsonMatch[0]) : null;
    } else {
      scores = aiResponse;
    }

    if (!scores || typeof scores !== 'object') {
      throw new Error("Could not parse AI response");
    }

    // Extract scores with validation
    const budgetScore = Math.max(1, Math.min(10, scores.budget_score || 5));
    const urgencyScore = Math.max(1, Math.min(10, scores.urgency_score || 5));
    const interestScore = Math.max(1, Math.min(10, scores.interest_score || 5));
    const decisionBonus = scores.decision_maker_bonus || 0;

    // Weighted calculation
    const baseScore = (
      (budgetScore * 0.40) + 
      (urgencyScore * 0.35) + 
      (interestScore * 0.25)
    );

    // Apply decision maker bonus
    const finalScore = Math.min(10, Math.round(baseScore + decisionBonus));

    // Determine category
    let category = '🔵 Cold';
    let priority = 'Low';
    let nextAction = 'Add to nurture sequence';

    if (finalScore >= 9) {
      category = '🔥 Hot';
      priority = 'Immediate';
      nextAction = 'Call within 2 hours';
    } else if (finalScore >= 7) {
      category = '🟡 Warm'; 
      priority = 'High';
      nextAction = 'Call within 24 hours';
    } else if (finalScore >= 5) {
      category = '🟢 Qualified';
      priority = 'Medium';
      nextAction = 'Email follow-up within 48 hours';
    } else if (finalScore >= 3) {
      category = '🔵 Cold';
      priority = 'Low';
      nextAction = 'Add to nurture sequence';
    } else {
      category = '❌ Unqualified';
      priority = 'None';
      nextAction = 'Disqualify or long-term nurture';
    }

    // Calculate follow-up date
    const followUpDate = new Date();
    switch(priority) {
      case 'Immediate': followUpDate.setHours(followUpDate.getHours() + 2); break;
      case 'High': followUpDate.setDate(followUpDate.getDate() + 1); break;
      case 'Medium': followUpDate.setDate(followUpDate.getDate() + 2); break;
      case 'Low': followUpDate.setDate(followUpDate.getDate() + 7); break;
      default: followUpDate.setDate(followUpDate.getDate() + 30);
    }

    return {
      // Individual scores
      budgetScore,
      urgencyScore, 
      interestScore,
      decisionBonus,

      // Final results
      finalScore,
      category,
      priority,
      nextAction,
      followUpDate: followUpDate.toISOString().split('T')[0],

      // Analysis from AI
      reasoning: scores.reasoning || 'AI analysis unavailable',
      confidence: scores.confidence_level || (finalScore >= 7 ? 'High' : finalScore >= 4 ? 'Medium' : 'Low'),
      redFlags: scores.red_flags || [],
      positiveSignals: scores.positive_signals || [],
      recommendedAction: scores.recommended_next_action || nextAction,
      closeProbability: scores.estimated_close_probability || (finalScore * 10),

      // Metadata
      scoredAt: new Date().toISOString(),
      leadId: leadData.leadId || leadData.Lead_ID || `LEAD_${Date.now()}`,

      // Quality indicators
      qualityFlags: {
        hasPhone: !!(leadData.phone || leadData.Phone),
        hasBudget: !(leadData.budget || leadData.Budget || '').toLowerCase().includes('not yet determined'),
        hasUrgency: !(leadData.timeline || leadData.Timeline || '').toLowerCase().includes('just researching'),
        isDecisionMaker: (leadData.role || leadData.Role || '').includes('Final decision maker'),
        hasSpecificNeeds: (leadData.needs || leadData.Notes || '').length > 50
      }
    };

  } catch (error) {
    console.error('AI scoring failed, using fallback:', error);
    return fallbackScoring(leadData);
  }
}

// Fallback scoring when AI fails
function fallbackScoring(leadData) {
  let budgetScore = 5;
  let urgencyScore = 5; 
  let interestScore = 5;
  let decisionBonus = 0;

  // Get budget data (handle different field names)
  const budget = (leadData.budget || leadData.Budget || '').toLowerCase();
  if (budget.includes('500,000') || budget.includes('over')) budgetScore = 9;
  else if (budget.includes('100,000')) budgetScore = 8;
  else if (budget.includes('50,000')) budgetScore = 7;
  else if (budget.includes('10,000')) budgetScore = 6;
  else if (budget.includes('under') || budget.includes('not yet')) budgetScore = 3;

  // Get timeline data (handle different field names)
  const timeline = (leadData.timeline || leadData.Timeline || '').toLowerCase();
  if (timeline.includes('immediately') || timeline.includes('1 month')) urgencyScore = 9;
  else if (timeline.includes('short-term') || timeline.includes('1-3')) urgencyScore = 7;
  else if (timeline.includes('medium-term') || timeline.includes('3-6')) urgencyScore = 5;
  else if (timeline.includes('long-term') || timeline.includes('6+')) urgencyScore = 3;
  else if (timeline.includes('researching')) urgencyScore = 2;

  // Get needs/notes data (handle different field names)
  const needs = leadData.needs || leadData.Notes || leadData.notes || '';
  if (needs.length > 200) interestScore = 8;
  else if (needs.length > 100) interestScore = 6;
  else if (needs.length > 50) interestScore = 4;
  else interestScore = 3;

  // Get role data (handle different field names)
  const role = leadData.role || leadData.Role || '';
  if (role.includes('Final decision maker')) decisionBonus = 1;
  else if (role.includes('Key influencer')) decisionBonus = 0.5;

  const baseScore = (budgetScore * 0.4) + (urgencyScore * 0.35) + (interestScore * 0.25);
  const finalScore = Math.min(10, Math.round(baseScore + decisionBonus));

  let category = '🔵 Cold';
  if (finalScore >= 8) category = '🔥 Hot';
  else if (finalScore >= 6) category = '🟡 Warm';
  else if (finalScore >= 4) category = '🟢 Qualified';

  return {
    budgetScore,
    urgencyScore,
    interestScore, 
    decisionBonus,
    finalScore,
    category,
    priority: finalScore >= 7 ? 'High' : finalScore >= 4 ? 'Medium' : 'Low',
    nextAction: finalScore >= 7 ? 'Call within 24 hours' : 'Email follow-up within 48 hours',
    reasoning: 'Fallback scoring used - AI evaluation unavailable',
    confidence: 'Medium',
    redFlags: [],
    positiveSignals: [],
    scoredAt: new Date().toISOString(),
    leadId: leadData.leadId || leadData.Lead_ID || `LEAD_${Date.now()}`
  };
}

// MAIN EXECUTION - HANDLES ALL POSSIBLE INPUT SCENARIOS
try {
  // Get lead data from current input
  const currentInput = $input.first().json;

  console.log('DEBUG - Current Input:', JSON.stringify(currentInput, null, 2));

  // Get AI response from current input or previous AI call
  let aiResponse;

  // Try to extract AI response from different possible formats
  if (currentInput.choices && currentInput.choices[0]) {
    // OpenAI format
    aiResponse = currentInput.choices[0].message.content;
  } else if (currentInput.response) {
    // Ollama format
    aiResponse = currentInput.response;
  } else if (currentInput.candidates && currentInput.candidates[0]) {
    // Gemini format
    aiResponse = currentInput.candidates[0].content.parts[0].text;
  } else if (currentInput.budget_score) {
    // Direct AI scoring response - THIS IS YOUR CASE
    aiResponse = currentInput;
  } else if (currentInput.output && currentInput.output.budget_score) {
    // AI response nested in output field
    aiResponse = currentInput.output;
  } else {
    // Use the whole input as AI response
    aiResponse = currentInput;
  }

  console.log('DEBUG - AI Response extracted:', JSON.stringify(aiResponse, null, 2));

  // For lead data, if we have AI scores in current input, we need original lead data
  let leadData;

  if (currentInput.budget_score || (currentInput.output && currentInput.output.budget_score)) {
    // Current input IS the AI response, try to get lead data from workflow context
    try {
      // Try different node names - replace with your actual node names
      leadData = $('Google Sheets Trigger').first().json ||
                 $('Webhook').first().json ||
                 $('Manual Trigger').first().json ||
                 $('Form Trigger').first().json ||
                 $('When clicking "Test workflow"').first().json ||
                 currentInput; // fallback to current input
    } catch (nodeError) {
      console.log('DEBUG - Could not find lead data in previous nodes, using current input');
      leadData = currentInput;
    }
  } else {
    // Use current input as lead data
    leadData = currentInput;
  }

  console.log('DEBUG - Lead Data:', JSON.stringify(leadData, null, 2));

  // Calculate the score
  const result = calculateLeadScore(aiResponse, leadData);

  console.log('DEBUG - Final Result:', JSON.stringify(result, null, 2));

  // Return the result
  return [{ json: result }];

} catch (error) {
  console.error('DEBUG - Execution failed:', error);

  // Emergency fallback - return basic scoring
  const basicData = $input.first().json;
  const fallbackResult = fallbackScoring(basicData);

  return [{ 
    json: {
      ...fallbackResult,
      error: 'Scoring calculation failed, using basic fallback',
      errorDetails: error.message,
      debugInfo: {
        inputData: basicData
      }
    }
  }];
}

